import{_ as l,a0 as p,w as r,s as o,ao as d,I as n,x as a,a1 as t,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"將安裝了 CentOS/RHEL 6/7 的機器轉變成路由器 | LCTT x X-CMD","titleTemplate":false,"description":"將安裝了 CentOS/RHEL 6/7 的機器轉變成路由器 | LCTT (201712) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"將安裝了 CentOS/RHEL 6/7 的機器轉變成路由器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"將安裝了 CentOS/RHEL 6/7 的機器轉變成路由器 | LCTT (201712) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201712/20171213 Turning a CentOS-RHEL 6 or 7 machine into a router","title":"將安裝了 CentOS/RHEL 6/7 的機器轉變成路由器","tag":"201712","desc":""},"relativePath":"201712/20171213 Turning a CentOS-RHEL 6 or 7 machine into a router.md","filePath":"[post].md"}'),h={name:"201712/20171213 Turning a CentOS-RHEL 6 or 7 machine into a router.md"};function g(u,s,c,b,k,f){const e=p("Link");return r(),o("div",null,[s[13]||(s[13]=d(`<h1 id="將安裝了-centos-rhel-6-7-的機器轉變成路由器" tabindex="-1">將安裝了 CentOS/RHEL 6/7 的機器轉變成路由器 <a class="header-anchor" href="#將安裝了-centos-rhel-6-7-的機器轉變成路由器" aria-label="Permalink to “將安裝了 CentOS/RHEL 6/7 的機器轉變成路由器”">​</a></h1><p>在本文中，我們將學習通過使用 NAT 技術將安裝有 RHEL/CentOS 6 &amp; 7 的機器轉變成路由器來用。 我們都知道，路由器是一個工作在第三層的網絡設備，用於將兩個或多個網絡連接在一起，即，將局域網連接上廣域網上或者局域網直接互聯。 路由器非常昂貴，尤其對於小型組織來説更是如此，這可能是我們關注路由器的一個原因。 與其使用專用硬件，不如讓我們用 Linux 機器轉換成路由器來用。</p><p>RHEL/CentOS 6 和 7 上的操作過程我們都會講。但在開始之前， 讓我們先看看需要準備那些東西。</p><h3 id="前期條件" tabindex="-1">前期條件 <a class="header-anchor" href="#前期條件" aria-label="Permalink to “前期條件”">​</a></h3><p>1、 一台裝有 RHEL/CentOS 6 或 7 的機器</p><p>2、兩塊分別配有本地 IP 和外網 IP 的網卡</p><p>我們需要為兩個網卡都分配 IP 地址，一個本地網絡的 IP（由我們的網絡管理員提供），另一個是互聯網 IP（由 ISP 提供）。 像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Ifcfg-en0s3 192.168.1.1 (LAN IP address)</span></span>
<span class="line"><span>Ifcfg-en0s5 10.1.1.1  (WAN IP address)</span></span></code></pre></div><p><strong>注意</strong> 不同 Linux 發行版的網卡名是不一樣的。</p><p>現在準備工作完成了，可以進行配置了。</p><h3 id="步驟-1-啓用-ip-轉發" tabindex="-1">步驟 1 啓用 IP 轉發 <a class="header-anchor" href="#步驟-1-啓用-ip-轉發" aria-label="Permalink to “步驟 1 啓用 IP 轉發”">​</a></h3><p>第一步，我們啓用 IP 轉發。 這一步在 RHEL/CentOS 6 和 7 上是相同的。 運行</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sysctl -w net.ipv4.ip_forward=1</span></span></code></pre></div><p>但是這樣會在系統重啓後恢復。要讓重啓後依然生效需要打開</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi /etc/sysctl.conf</span></span></code></pre></div><p>然後輸入下面內容，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>net.ipv4.ip_forward = 1</span></span></code></pre></div><p>保存並退出。現在系統就啓用 IP 轉發了。</p><h3 id="步驟-2-配置-iptables-firewalld-的規則" tabindex="-1">步驟 2 配置 IPtables/Firewalld 的規則 <a class="header-anchor" href="#步驟-2-配置-iptables-firewalld-的規則" aria-label="Permalink to “步驟 2 配置 IPtables/Firewalld 的規則”">​</a></h3><p>下一步我們需要啓動 IPtables/firewalld 服務並配置 NAT 規則，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ systemctl start firewalld (For Centos/RHEL 7)</span></span>
<span class="line"><span>$ service iptables start  (For Centos/RHEL 6)</span></span></code></pre></div><p>然後運行下面命令來配置防火牆的 NAT 規則：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CentOS/RHEL 6</span></span>
<span class="line"><span>$ iptables -t nat -A POSTROUTING -o XXXX -j MASQUERADE</span></span>
<span class="line"><span>$ service iptables restart </span></span>
<span class="line"><span>CentOS/RHEL 7</span></span>
<span class="line"><span>$ firewall-cmd  -permanent -direct -passthrough ipv4 -t nat -I POSTROUTING -o XXXX -j MASQUERADE -s 192.168.1.0/24</span></span>
<span class="line"><span>$ systemctl restart firewalld</span></span></code></pre></div><p>這裏，<code>XXXX</code> 是配置有外網 IP 的那個網卡名稱。 這就將 Linux 機器配置成了路由器了， 下面我們就可以配置客户端然後測試路由器了。</p><h3 id="步驟-3-配置客户端" tabindex="-1">步驟 3 配置客户端 <a class="header-anchor" href="#步驟-3-配置客户端" aria-label="Permalink to “步驟 3 配置客户端”">​</a></h3><p>要測試路由器，我們需要在客户端的網關設置成內網 IP， 本例中就是 192.168.1.1。 因此不管客户機是 Windows 還是 Linux， 請先確保網關是 192.168.1.1。 完成後， 打開終端或命令列並 <code>ping</code> 一個網站來測試客户端是否能訪問互聯網了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ping google.com</span></span></code></pre></div><p>我們也可以通過網絡瀏覽器訪問網站的方式來檢查。</p><hr>`,29)),n("p",null,[s[1]||(s[1]=a("via: ",-1)),t(e,{href:"http://linuxtechlab.com/turning-centosrhel-6-7-machine-router/"},{default:i(()=>[...s[0]||(s[0]=[a("http://linuxtechlab.com/turning-centosrhel-6-7-machine-router/",-1)])]),_:1})]),n("p",null,[s[5]||(s[5]=a("作者：",-1)),t(e,{href:"http://linuxtechlab.com/author/shsuain/"},{default:i(()=>[...s[2]||(s[2]=[a("Shusain",-1)])]),_:1}),s[6]||(s[6]=a(" 譯者：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[7]||(s[7]=a(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[10]||(s[10]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:i(()=>[...s[9]||(s[9]=[a("Linux中國",-1)])]),_:1}),s[12]||(s[12]=a(" 榮譽推出",-1))])])}const T=l(h,[["render",g]]);export{L as __pageData,T as default};
